import React from 'react';

const Skills = () => (
  <div>
    <h2>Skills</h2>
    <ul className="list-group">
      <li className="list-group-item">Figma, Canva, Adobe Express, CorelDRAW</li>
      <li className="list-group-item">HTML, CSS, JavaScript</li>
      <li className="list-group-item">Project Management, Leadership</li>
    </ul>
  </div>
);

export default Skills;
